package com.moddingfromamod.cbscript.py;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Differential test of {@link PyEval} against CPython: every case of {@code pyeval_cases.tsv} (generated by
 * {@code tools/pyeval_cases.py} with python3) must give the same {@code repr()} of the result, or the same exception
 * type and message, and the same {@code print()} output.
 *
 * <p>JDK only: {@code java -cp <classes>:<resources> com.moddingfromamod.cbscript.py.PyEvalDifferentialTest [tsv]}.
 * Exits with status 1 if any case differs.
 */
public final class PyEvalDifferentialTest {
    /** The locals every case sees; must match LOCALS in tools/pyeval_cases.py. */
    private static final String[][] LOCALS = {
        {"i", "7"}, {"f", "2.5"}, {"s", "'text'"}, {"l", "[1, 2, 3]"}, {"t", "(4, 5)"},
        {"d", "{'a': 1, 'b': [2, 3]}"}, {"e", "[]"}, {"neg", "-3"}, {"big", "2 ** 70"}, {"name", "'Moddy'"},
        {"x", "0.1"}, {"n", "0"}, {"u", "'é☃😀'"}, {"nested", "[[1, 2], [3, [4, 5]]]"},
    };

    private PyEvalDifferentialTest() {}

    private static String unescape(String s) {
        StringBuilder sb = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\\' && i + 1 < s.length()) {
                char n = s.charAt(++i);
                sb.append(switch (n) {
                    case 't' -> '\t';
                    case 'n' -> '\n';
                    case 'r' -> '\r';
                    default -> n;
                });
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    private static Map<String, PyObject> freshLocals() {
        Map<String, PyObject> m = new LinkedHashMap<>();
        for (String[] kv : LOCALS) {
            m.put(kv[0], PyEval.eval(kv[1], Map.of()));
        }
        return m;
    }

    /** Evaluates one case the way the generator did; returns {result, printed}. */
    static String[] run(String expr) {
        StringBuilder printed = new StringBuilder();
        String result;
        try {
            PyObject v = PyEval.eval(expr, freshLocals(), printed::append);
            result = "R:" + v.repr();
        } catch (PyException e) {
            result = "E:" + e.type + ": " + e.pyStr;
        } catch (RuntimeException | StackOverflowError e) {
            result = "JAVA:" + e;
        }
        return new String[] {result, printed.toString()};
    }

    private static List<String> readCases(String[] args) throws IOException {
        InputStream in;
        if (args.length > 0) {
            in = Files.newInputStream(Path.of(args[0]));
        } else {
            in = PyEvalDifferentialTest.class.getResourceAsStream("/pyeval_cases.tsv");
            if (in == null) {
                throw new IOException("pyeval_cases.tsv not on the classpath (pass its path as an argument)");
            }
        }
        List<String> lines = new ArrayList<>();
        try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            String line;
            while ((line = r.readLine()) != null) {
                if (!line.isEmpty()) {
                    lines.add(line);
                }
            }
        }
        return lines;
    }

    public static void main(String[] args) throws IOException {
        System.setOut(new java.io.PrintStream(new java.io.FileOutputStream(java.io.FileDescriptor.out), true,
                StandardCharsets.UTF_8));
        List<String> lines = readCases(args);
        int pass = 0;
        int fail = 0;
        long start = System.nanoTime();
        for (String line : lines) {
            String[] cols = line.split("\t", -1);
            String expr = unescape(cols[0]);
            String expected = unescape(cols[1]);
            String expectedPrint = cols.length > 2 ? unescape(cols[2]) : "";
            String[] got = run(expr);
            if (got[0].equals(expected) && got[1].equals(expectedPrint)) {
                pass++;
            } else {
                fail++;
                if (fail <= 200) {
                    System.out.println("FAIL: " + expr);
                    System.out.println("  expected: " + expected + (expectedPrint.isEmpty() ? ""
                            : "  printed: " + expectedPrint.replace("\n", "\\n")));
                    System.out.println("  got:      " + got[0] + (got[1].isEmpty() ? ""
                            : "  printed: " + got[1].replace("\n", "\\n")));
                }
            }
        }
        long ms = (System.nanoTime() - start) / 1_000_000;
        System.out.println("PyEvalDifferentialTest: " + pass + " passed, " + fail + " failed, " + lines.size()
                + " cases (" + ms + " ms)");
        if (fail > 0) {
            System.exit(1);
        }
    }
}
